                        var linePoints = geom.Points;
                        if (linePoints.Count != 2) throw new ArgumentException("A line must have exactly two points.");
                        var line = (Line)_document.CreateEntity(EntityType.Line, linePoints[0], linePoints[1]); // Verify CreateEntity method exists and works correctly
                        _table.SetCellContent(rowIndex, columnIndex, line); // Verify SetCellContent method exists and works correctly
                        break;

                    case GeometryType.Circle:
                        // Assuming Attributes property contains the radius of the circle
                        var radius = geom.Attributes["Radius"];
                        var center = geom.Points[0]; // Assuming the first point is the center
                        var circle = (Circle)_document.CreateEntity(EntityType.Circle, center, radius); // Verify CreateEntity method exists and works correctly
                        _table.SetCellContent(rowIndex, columnIndex, circle); // Verify SetCellContent method exists and works correctly
                        break;

                    default:
                        throw new NotSupportedException($"Geometry type {geom.Type} is not supported.");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while embedding primitives: {ex.Message}");
        }
    }
}

