```python
# This script extends a basic LL(1) parser to handle a variety of C-like expressions and statements,
# including arithmetic, assignment, comma-separated, relational, logical, loop, selection, jump, and function call statements.
# It computes the First and Follow sets for the grammar, builds an LL(1) parsing table, and parses input strings based on this table.
# Enhanced error handling provides meaningful feedback for parsing errors, including specific input and expected tokens.
# Explicitly demonstrates handling of nested expressions and operator precedence.

def compute_first_sets(grammar):
    """Computes the First set for each non-terminal in the grammar."""
    firsts = {symbol: set() for symbol in grammar}
    changed = True

    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                if production[0].islower() or production[0] == '$':
                    if production[0] not in firsts[symbol]:
                        firsts[symbol].add(production[0])
                        changed = True
                elif production[0] != 'ε':
                    for token in production:
                        if 'ε' in firsts[token]:
                            firsts[symbol] |= firsts[token] - {'ε'}
                        else:
                            firsts[symbol] |= firsts[token]
                            break
                else:
                    if 'ε' not in firsts[symbol]:
                        firsts[symbol].add('ε')
                        changed = True

    return firsts


def compute_follow_sets(grammar, firsts):
    """Computes the Follow set for each non-terminal in the grammar."""
    follows = {symbol: set() for symbol in grammar}
    follows['S'].add('$')

    changed = True
    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                for i, token in enumerate(production):
                    if token.isupper():
                        if i + 1 < len(production):
                            first_next = firsts[production[i + 1]]
                            if 'ε' in first_next:
                                follows[token] |= first_next - {'ε'}
                                follows[token] |= follows[symbol]
                            else:
                                follows[token] |= first_next
                        else:
                            follows[token] |= follows[symbol]
                        if 'ε' in firsts[token]:
                            follows[token] |= follows[symbol]
                            changed = True

    return follows


def build_ll1_table(grammar, firsts, follows):
    """Builds the LL(1) parsing table using the computed First and Follow sets."""
    table = {}
    for symbol in grammar:
        table[symbol] = {}
        for production in grammar[symbol]:
            for token in firsts[symbol]:
                if token != 'ε':
                    table[symbol][token] = production
            if 'ε' in firsts[symbol]:
                for token in follows[symbol]:
                    table[symbol][token] = production

    return table


# Grammar rules for the C-like language
# Extended to handle nested expressions, operator precedence, and multiple statements
grammar = {
    'S': ['<Expression>', '<StatementList>'],
    'Expression': ['<ArithmeticExpression>', '<AssignmentExpression>', '<CommaExpression>', '<RelationalExpression>', '<LogicalExpression>'],
    'ArithmeticExpression': ['<Term> <ArithmeticExpressionPrime>'],  # Handles arithmetic operations by breaking them into terms and arithmetic expression continuation
    'ArithmeticExpressionPrime': ['<Operator> <Term> <ArithmeticExpressionPrime>', 'ε'],  # Deals with repeated application of addition and subtraction
    'Term': ['<Factor> <TermPrime>'],  # Handles terms which include multiplication and division inside arithmetic expressions
    'TermPrime': ['"*" <Factor> <TermPrime>', '"/" <Factor> <TermPrime>', 'ε'],  # Deals with repeated multiplication and division
    'Factor': ['<Number>', '<Variable>', '"(" <Expression> ")"'],  # Support for nested expressions in parentheses
    'AssignmentExpression': ['<Variable> "=" <Expression>'],  # Handles assignment statements
    'CommaExpression': ['<Expression> "," <Expression>'],  # Handles comma-separated expressions
    'RelationalExpression': ['<Expression> <RelationalOperator> <Expression>'],  # Handles relational comparisons
    'LogicalExpression': ['<RelationalExpression> "&&" <LogicalExpression>', '<RelationalExpression> "||" <LogicalExpression>', '"!" <RelationalExpression>'],  # Handles logical operations
    'StatementList': ['<Statement> [";" <StatementList>]'],  # Allows for a list of statements
    'Statement': ['<Expression>', '<LoopStatement>', '<SelectionStatement>', '<JumpStatement>', '<FunctionCall>'],  # Represents individual statements
    'LoopStatement': ['"for" "(" <Expression> ";" <Expression> ";" <Expression> ")" "{" <StatementList> "}"', '"while" "(" <Expression> ")" "{" <StatementList> "}"'],  # Supports for and while loops
    'SelectionStatement': ['"if" "(" <Expression> ")" "{" <StatementList> "}" ["else" "{" <StatementList> "}"]', '"switch" "(" <Expression> ")" "{" <CaseList> "default" ":" <StatementList> "}"'],  # Supports if-else and switch-case statements
    'JumpStatement': ['"break"', '"continue"', '"return" <Expression>'],  # Supports break, continue, and return
    'FunctionCall': ['<Identifier> "(" <ArgumentList> ")"'],  # Handles function calls
    'CaseList': ['"case" <Expression> ":" <StatementList> ["case" <Expression> ":" <StatementList>]'],  # Handles cases in switch-case statements
    'ArgumentList': ['<Expression> ["," <Expression>]'],  # Handles arguments for function calls
    'Operator': ['"+"', '"-"'],  # Arithmetic operators
    'RelationalOperator': ['"<"', '">"', '"<="', '">="', '"=="', '"!="'],  # Relational operators
    'Number': ['[0-9]+'],  # Numeric literals
    'Variable': ['[a-zA-Z][a-zA-Z0-9]*'],  # Variable names
