const fs = require('fs');
const Jimp = require('jimp');

/**
 * Adds a watermark to an image and saves the result.
 * @param {string} imagePath - Path to the source image.
 * @param {Array<string>} watermarkPaths - Array of paths to watermark images.
 * @param {string} outputImagePath - Path to save the output image.
 */
async function addWatermarkToImage(imagePath, watermarkPaths, outputImagePath) {
    // Load the image using Jimp
    const image = await Jimp.read(imagePath);

    // Calculate the density of each corner considering edges
    const cornersDensity = calculateCornersDensityWithAdvancedEdges(image);
    const bestCorner = Object.keys(cornersDensity).reduce((a, b) => cornersDensity[a] < cornersDensity[b] ? a : b);

    // Choose the appropriate watermark size
    let chosenWatermark;
    for (const path of watermarkPaths) {
        const watermark = await Jimp.read(path);
        if (watermark.bitmap.width <= image.bitmap.width / 4 && watermark.bitmap.height <= image.bitmap.height / 4) {
            chosenWatermark = watermark;
            break;
        }
    }

    if (!chosenWatermark) {
        console.error("No suitable watermark found");
        return;
    }

    // Apply transparency to the watermark
    chosenWatermark.opacity(0.5); // 50% opacity

    // Determine the position based on the best corner
    const position = getPosition(bestCorner, image, chosenWatermark);

    // Place the watermark
    image.composite(chosenWatermark, position.x, position.y);

    // Save the resulting image
    image.write(outputImagePath);
}

/**
 * Calculates the density of each corner of the image.
 * @param {Jimp} image - The image to analyze.
 * @returns {Object} - An object containing the density of each corner.
 */
function calculateCornersDensityWithAdvancedEdges(image) {
    const cornerSize = Math.min(image.bitmap.width, image.bitmap.height) / 8;
    const corners = {
        topLeft: getCornerDensityWithAdvancedEdges(image, 0, 0, cornerSize),
        topRight: getCornerDensityWithAdvancedEdges(image, image.bitmap.width - cornerSize, 0, cornerSize),
        bottomLeft: getCornerDensityWithAdvancedEdges(image, 0, image.bitmap.height - cornerSize, cornerSize),
        bottomRight: getCornerDensityWithAdvancedEdges(image, image.bitmap.width - cornerSize, image.bitmap.height - cornerSize, cornerSize)
    };
    return corners;
}

/**
 * Computes the edge density for a given corner using an advanced gradient-based approach.
 * @param {Jimp} image - The image to analyze.
 * @param {number} startX - Starting X coordinate of the corner.
 * @param {number} startY - Starting Y coordinate of the corner.
 * @param {number} size - Size of the corner to analyze.
 * @returns {number} - The average gradient (edge density) of the corner.
 */
function getCornerDensityWithAdvancedEdges(image, startX, startY, size) {
    let sum = 0;
    for (let x = startX; x < startX + size; x++) {
        for (let y = startY; y < startY + size; y++) {
            const pixel = image.getPixelColor(x, y);
            const rgba = Jimp.intToRGBA(pixel);
            // Advanced gradient detection using Sobel operator approximation
            const gradientX = Math.abs(rgba.r - (x < image.bitmap.width - 1 ? Jimp.intToRGBA(image.getPixelColor(x + 1, y)).r : 0));
            const gradientY = Math.abs(rgba.r - (y < image.bitmap.height - 1 ? Jimp.intToRGBA(image.getPixelColor(x, y + 1)).r : 0));
            const gradientMagnitude = Math.sqrt(gradientX * gradientX + gradientY * gradientY); // Euclidean distance for gradient magnitude
            sum += gradientMagnitude;
        }
    }
    return sum / (size * size); // Average gradient magnitude
}

/**
 * Determines the position to place the watermark based on the corner.
 * @param {string} corner - The corner name ('topLeft', 'topRight', 'bottomLeft', 'bottomRight').
 * @param {Jimp} image - The main image.
 * @param {Jimp} watermark - The watermark image.
 * @returns {{x: number, y: number}} - The position coordinates.
 */
function getPosition(corner, image, watermark) {
    switch (corner) {
        case 'topLeft':
            return { x: 0, y: 0 };
        case 'topRight':
            return { x: image.bitmap.width - watermark.bitmap.width, y: 0 };
        case 'bottomLeft':
            return { x: 0, y: image.bitmap.height - watermark.bitmap.height };
        case 'bottomRight':
            return { x: image.bitmap.width - watermark.bitmap.width, y: image.bitmap.height - watermark.bitmap.height };
        default:
            throw new Error('Invalid corner');
    }
}

